#include "V1Import.hpp"

#include "../Support/AppFolders.hpp"

#include "libslic3r_version.h"


#include <nlohmann/json.hpp>

#include <algorithm>
#include <chrono>
#include <ctime>
#include <fstream>
#include <sstream>

namespace Slic3r::GUI::JusPrin::V1Import {

namespace fs = std::filesystem;
using nlohmann::json;

namespace {

// v1's app key, which names its folder and its settings file.
constexpr const char* kV1Key = "JusPrin";
// Where JusPrin 2 keeps what it writes for itself inside its data folder.
constexpr const char* kReportPath = "jusprin/v1-import.json";


std::string now_utc()
{
    const std::time_t now = std::chrono::system_clock::to_time_t(std::chrono::system_clock::now());
    char              text[32];
    std::strftime(text, sizeof(text), "%Y-%m-%dT%H:%M:%SZ", std::gmtime(&now));
    return text;
}

std::optional<json> read_json(const fs::path& path)
{
    std::ifstream in(path, std::ios::binary);
    if (!in)
        return std::nullopt;
    std::stringstream text;
    text << in.rdbuf();
    json parsed = json::parse(text.str(), nullptr, false);
    if (parsed.is_discarded())
        return std::nullopt;
    return parsed;
}

bool write_text(const fs::path& path, const std::string& text)
{
    std::error_code ec;
    fs::create_directories(path.parent_path(), ec);
    std::ofstream out(path, std::ios::binary | std::ios::trunc);
    out << text;
    return static_cast<bool>(out);
}

// Copies every file under `from` to the same place under `to`, recording
// any that fail (by their path inside v1's folder) and going on.
void copy_tree(const fs::path& from, const fs::path& to, const fs::path& v1, std::vector<std::string>& failed)
{
    std::error_code ec;
    if (!fs::is_directory(from, ec))
        return;
    for (fs::recursive_directory_iterator it(from, ec), end; it != end && !ec; it.increment(ec)) {
        const fs::path target = to / fs::relative(it->path(), from);
        std::error_code step;
        if (fs::is_directory(it->path(), step))
            fs::create_directories(target, step);
        else {
            fs::create_directories(target.parent_path(), step);
            if (!step)
                fs::copy_file(it->path(), target, fs::copy_options::overwrite_existing, step);
        }
        if (step)
            failed.push_back(fs::relative(it->path(), v1).generic_u8string());
    }
    if (ec)
        failed.push_back(fs::relative(from, v1).generic_u8string());
}

// A user preset's name is its file's, without ".json".
std::vector<std::string> preset_names(const fs::path& folder)
{
    std::vector<std::string> names;
    std::error_code ec;
    if (!fs::is_directory(folder, ec))
        return names;
    for (fs::directory_iterator it(folder, ec), end; it != end && !ec; it.increment(ec))
        if (it->path().extension() == ".json")
            names.push_back(it->path().stem().u8string());
    std::sort(names.begin(), names.end());
    return names;
}

// v1's settings as JusPrin 2's: everything carries over as it is (OrcaSlicer
// reads an older settings file the way it reads its own from an earlier
// version), except v1's JusPrin sign-in. v1 signed in with an Obico account,
// and JusPrin 2 accounts are JusPrin's own, on JusPrin's server, so v1's token
// and the server it signed in to (jusprin_server) stay behind and the person
// signs up again.
// v1's version number is replaced by this app's, the one OrcaSlicer writes
// there at every launch. OrcaSlicer reads it as the version these settings
// were last saved by, and for anything older than 2.4.0 it opens a notice
// about moving profile sync from Bambu Cloud to Orca Cloud, over the
// welcome-back window. Erasing it instead would turn auto-backup back on.
json carried_settings(json settings)
{
    if (!settings.is_object())
        return settings;
    settings.erase("jusprin_server");
    if (auto app = settings.find("app"); app != settings.end() && app->is_object())
        (*app)["version"] = SoftFever_VERSION;
    return settings;
}

} // namespace

json to_json(const Report& report)
{
    return json{{"source", report.source},           {"importedAt", report.imported_at}, {"printers", report.printers},
                {"presets", report.presets},         {"connections", report.connections},
                {"preferences", report.preferences}, {"failed", report.failed},
                {"pending", report.pending}};
}

Report report_from_json(const json& json)
{
    Report report;
    report.source      = json.value("source", "");
    report.imported_at = json.value("importedAt", "");
    report.printers    = json.value("printers", std::vector<std::string>{});
    report.presets     = json.value("presets", std::vector<std::string>{});
    report.connections = json.value("connections", std::vector<std::string>{});
    report.preferences = json.value("preferences", false);
    report.failed      = json.value("failed", std::vector<std::string>{});
    report.pending     = json.value("pending", false);
    return report;
}

fs::path v1_folder() { return installed_app_folder(kV1Key, "JUSPRIN_V1_DATADIR"); }

std::optional<Report> import_if_first_launch(const fs::path& data_dir, const fs::path& v1, const std::string& app_key)
{
    std::error_code ec;
    const fs::path settings_file = data_dir / (app_key + ".conf");
    const fs::path v1_settings   = v1 / (std::string(kV1Key) + ".conf");
    if (v1.empty() || fs::exists(settings_file, ec) || !fs::is_regular_file(v1_settings, ec))
        return std::nullopt;

    Report report;
    report.source      = v1.u8string();
    report.imported_at = now_utc();

    // The person's own presets. A printer preset carries its network
    // connection (print_host and its key), so connections come with it.
    copy_tree(v1 / "user", data_dir / "user", v1, report.failed);
    for (const char* file : {"BambuNetworkEngine.conf"}) {
        if (!fs::is_regular_file(v1 / file, ec))
            continue;
        std::error_code step;
        fs::copy_file(v1 / file, data_dir / file, fs::copy_options::overwrite_existing, step);
        if (step)
            report.failed.push_back(file);
    }
    for (fs::directory_iterator user(data_dir / "user", ec), end; user != end && !ec; user.increment(ec)) {
        if (!fs::is_directory(user->path(), ec))
            continue;
        for (const std::string& name : preset_names(user->path() / "machine")) {
            report.printers.push_back(name);
            const std::optional<json> preset = read_json(user->path() / "machine" / (name + ".json"));
            if (preset && preset->is_object() && !preset->value("print_host", "").empty())
                report.connections.push_back(name);
        }
        for (const char* kind : {"filament", "process"})
            for (const std::string& name : preset_names(user->path() / kind))
                report.presets.push_back(name);
    }

    // The settings file last: its presence is what says the import is done,
    // so a crash before this point imports again next launch.
    if (const std::optional<json> settings = read_json(v1_settings)) {
        const json carried = carried_settings(*settings);
        report.preferences = write_text(settings_file, carried.dump(4));
        if (!report.preferences)
            report.failed.push_back(std::string(kV1Key) + ".conf");
    } else {
        report.failed.push_back(std::string(kV1Key) + ".conf");
    }
    write_text(data_dir / kReportPath, to_json(report).dump(2));
    return report;
}

void import_on_first_launch(const std::string& data_dir)
{
    import_if_first_launch(fs::u8path(data_dir), v1_folder(), SLIC3R_APP_KEY);
}

std::optional<Report> read_report(const fs::path& data_dir)
{
    const std::optional<json> stored = read_json(data_dir / kReportPath);
    if (!stored || !stored->is_object())
        return std::nullopt;
    return report_from_json(*stored);
}

void mark_shown(const fs::path& data_dir)
{
    std::optional<Report> report = read_report(data_dir);
    if (!report)
        return;
    report->pending = false;
    write_text(data_dir / kReportPath, to_json(*report).dump(2));
}

} // namespace Slic3r::GUI::JusPrin::V1Import

#pragma once

// Bringing a JusPrin v1 setup into JusPrin 2 on first launch.
//
// JusPrin 2 has its own data folder ("JusPrin2"), so without this a person
// coming from v1 would start with no printers, presets or preferences. The
// first time JusPrin 2 starts with no settings file of its own, and v1's
// folder is where v1 keeps it on this computer, the parts of v1's folder that
// belong to the person are copied: the user presets (printers, filaments, processes, and
// with the printers their network connections), Bambu's network settings,
// and v1's settings file, whose JusPrin account sign-in becomes JusPrin 2's.
// v1's folder is only read. What was copied is written down for the
// welcome-back screen, which shows it once.
//
// Runs before OrcaSlicer reads its settings or presets, from GUI_App's
// start-up, and so is plain file work: no GUI, no AppConfig. Paths are
// UTF-8 strings where they cross into OrcaSlicer, std::filesystem inside.

#include <nlohmann/json_fwd.hpp>

#include <filesystem>

#include <optional>
#include <string>
#include <vector>

namespace Slic3r::GUI::JusPrin::V1Import {

// What the import copied, as the welcome-back screen lists it.
struct Report
{
    std::string              source;      // v1's folder
    std::string              imported_at; // UTC, ISO 8601
    std::vector<std::string> printers;    // user printer presets, by name
    std::vector<std::string> presets;     // user filament and process presets
    std::vector<std::string> connections; // printers with a network connection
    bool                     preferences{false};
    // Files that could not be copied, by their path inside v1's folder.
    std::vector<std::string> failed;
    // Still to be shown on the welcome-back screen.
    bool                     pending{true};
};

nlohmann::json to_json(const Report& report);
Report         report_from_json(const nlohmann::json& json);

// Where v1 keeps its folder: v1's default folder for the platform, whatever
// folder JusPrin 2 was started with, so a run on a scratch --datadir still
// finds the person's v1 setup. JUSPRIN_V1_DATADIR names another folder, and
// set to "" means none: test runs set it so they never read a real v1 setup.
std::filesystem::path v1_folder();

// Copies v1's setup into `data_dir` when JusPrin 2 has no settings file
// there yet and `v1` holds one, and writes the report. Nothing otherwise.
// `app_key` names the settings files ("JusPrin2" for JusPrin2.conf).
std::optional<Report> import_if_first_launch(const std::filesystem::path& data_dir, const std::filesystem::path& v1,
                                             const std::string& app_key);

// The start-up call: v1_folder() and import_if_first_launch() for this run.
void import_on_first_launch(const std::string& data_dir);

// The report a previous import left, if any.
std::optional<Report> read_report(const std::filesystem::path& data_dir);
// Records that the welcome-back screen has been shown.
void mark_shown(const std::filesystem::path& data_dir);

} // namespace Slic3r::GUI::JusPrin::V1Import

